local SelectServerNode = Class('SelectServerNode')

function SelectServerNode:__init()
    self._data = nil 
    self.cb = nil

end

function SelectServerNode:__delete()
    self._data = nil
    self.cb = nil
end

function SelectServerNode:Awake()
    local tagNode2 = self.TagNode.transform.parent:Find("TagNode2")
    if tagNode2 then
        self.TagNode2 = KTool.GetComponent(tagNode2.gameObject, typeof(UISwitchImage))
    end
end

function SelectServerNode:SetCallBack(cb)
    self.cb = cb
end



function SelectServerNode:Start()

end

function SelectServerNode:UpdateUI(data)
    if isNull(data) then
        return
    end
    self._data = data
    local serverName = data.serverName
    local serverStatus = data.status
    local isNew =  checkInt(data.isNew)
    local serverRecommendedStatus =  checkInt(data.isRecommend)
    local playerName = data.playerName
    if (data.playerName and string.len(data.playerName) == 0) or isNull(data.playerName) then
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        ---@type ServerDojo
        local serverDojo =  userComponent:GetServerById(data.serverId) 
        if serverDojo then
            playerName = serverDojo.playerName    
        end
    end
    
    KTool.SetActive(self.TagNode.gameObject , false)
    CfUtils.SetActive(self.TagNode2, false)

    if serverRecommendedStatus == 1 and isNew == 1  then
        self.TagNode.Status = serverRecommendedStatus
        CfUtils.SetUISwitchText(self.Text, serverRecommendedStatus)
        KTool.SetActive(self.TagNode.gameObject , true)  
        CfUtils.SetUISwitchImage(self.TagNode2, 2)
        self.Text2.Status = 2  
        CfUtils.SetActive(self.TagNode2, true)
    else 
        local status = 0
        if serverRecommendedStatus == 1 then
            status = 1
        elseif isNew == 1 then
            status = 2
        end
        if status > 0  then
            self.TagNode.Status = status
            self.Text.Status = status  
            KTool.SetActive(self.TagNode.gameObject , true)  
        end
           
    end
    -- if serverRecommendedStatus == 1 then
    --     self.TagNode.Status = serverRecommendedStatus
    --     self.Text.Status = serverRecommendedStatus  
    --     KTool.SetActive(self.TagNode.gameObject , true)  
    -- else 
    --     if isNew == 1 then
    --         self.TagNode.Status = 2
    --         self.Text.Status = 2
    --         KTool.SetActive(self.TagNode.gameObject , true)
    --     else 
    --         KTool.SetActive(self.TagNode.gameObject , false)
    --     end
    -- end
    if  checkInt(serverStatus) == 0  then
        KTool.SetActive(self.ImgStatusIcon , false)
    else     
        KTool.SetActive(self.ImgStatusIcon , true)
        self.ImgStatusIcon.Status = serverStatus    
    end
    CfUtils.FillText(self.TxtName1, serverName)
    CfUtils.FillText(self.TxtName2, playerName)
    SetButtonAction(self.ButtonGroup , function ()
        if self.cb then
            self.cb(self._data.serverId)
        end    
    end)
end


function SelectServerNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return SelectServerNode